// Nodu colour preview page: palette / theme / colour-vision switches, generated tables and copy helpers.
// Data comes from tokens.js (window.NODU), generated by build-palette-page.cjs.
(() => {
    'use strict';
    const N = window.NODU;
    if (!N) return;
    const root = document.documentElement;
    const $ = (sel, el = document) => el.querySelector(sel);
    const $$ = (sel, el = document) => [...el.querySelectorAll(sel)];
    const THEMES = ['light', 'dark'];
    const CVD = ['none', 'protanopia', 'deuteranopia', 'tritanopia', 'achromatopsia'];
    const INK = N.core.ink.hex, WHITE = '#FFFFFF';

    // ---------- state (URL query makes any combination shareable) ----------
    const params = new URLSearchParams(location.search);
    const state = {
        palette: N.palettes[params.get('palette')] ? params.get('palette') : 'board',
        theme: THEMES.includes(params.get('theme')) ? params.get('theme') : 'light',
        cvd: CVD.includes(params.get('cvd')) ? params.get('cvd') : 'none'
    };
    const tokens = () => N.tokens[state.palette][state.theme];

    // ---------- colour maths (same formulas as palette.cjs) ----------
    const channel = v => { const c = v / 255; return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4; };
    const luminance = hex => {
        const n = parseInt(hex.slice(1, 7), 16);
        return 0.2126 * channel((n >> 16) & 255) + 0.7152 * channel((n >> 8) & 255) + 0.0722 * channel(n & 255);
    };
    const contrast = (a, b) => { const [x, y] = [luminance(a), luminance(b)].sort((p, q) => q - p); return (x + 0.05) / (y + 0.05); };
    const fmt = v => `${v.toFixed(1)}:1`;
    const rgbText = hex => { const n = parseInt(hex.slice(1, 7), 16); return `${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}`; };
    const bestText = hex => (contrast(WHITE, hex) >= contrast(INK, hex) ? WHITE : INK);
    const grade = v => (v >= 7 ? 'AAA' : v >= 4.5 ? 'AA' : v >= 3 ? '大字 / 图形' : '不达标');

    const LABELS = {
        'brand-blue': '品牌蓝', signal: '点亮黄', 'on-signal': '点亮黄上的文字', ink: '芯片墨', paper: '丝印白',
        canvas: '画布', editor: '编辑区', panel: '面板', surface: '表面', raised: '抬升', hover: '悬停', border: '分隔线',
        'border-strong': '输入框边框', input: '输入底', text: '正文', 'text-2': '次要文字', 'text-muted': '弱化文字',
        'text-disabled': '禁用文字', terminal: '终端底', idle: '未连接', ok: '成功', warn: '警告', error: '错误',
        'idle-bg': '未连接底', 'ok-bg': '成功底', 'warn-bg': '警告底', 'error-bg': '错误底', 'signal-bg': '里程碑底',
        primary: '主色', 'on-primary': '主按钮文字', 'primary-hover': '主色悬停', 'primary-active': '主色按下',
        accent: '强调文字 / 链接', focus: '焦点环', marker: '活动标记', busy: '进行中', 'busy-bg': '进行中底',
        selection: '选中底', 'editor-selection': '编辑区选区', soft: '柔和底'
    };
    // Ten neutrals per theme, named as their CSS variables (--nd-*).
    const NEUTRAL_KEYS = [['canvas', 'canvas'], ['editor', 'editor'], ['panel', 'panel'], ['surface', 'surface'], ['raised', 'raised'],
        ['hover', 'hover'], ['border', 'border'], ['borderStrong', 'border-strong'], ['textMuted', 'text-muted'], ['text', 'text']];
    const SYNTAX_LABELS = { comment: '注释', keyword: '关键字', string: '字符串', number: '数字', function: '函数', type: '类型', variable: '变量', punctuation: '标点' };
    const label = key => LABELS[key] || (key.startsWith('syn-') ? `语法 · ${SYNTAX_LABELS[key.slice(4)] || key.slice(4)}`
        : key.startsWith('ansi-') ? `ANSI ${key.slice(5)}` : key);
    const el = (tag, attrs = {}, html = '') => {
        const node = document.createElement(tag);
        for (const [k, v] of Object.entries(attrs)) node.setAttribute(k, v);
        if (html) node.innerHTML = html;
        return node;
    };

    // ---------- logos ----------
    function injectLogos() {
        for (const host of $$('[data-logo]')) {
            host.innerHTML = N.logos[host.dataset.logo] || '';
            const svg = host.querySelector('svg');
            if (svg && host.hasAttribute('data-decorative')) {
                svg.setAttribute('aria-hidden', 'true');
                svg.removeAttribute('role');
                svg.removeAttribute('aria-label');
                svg.querySelector('title')?.remove();
            }
        }
    }

    // ---------- copy + toast ----------
    let toastTimer;
    function toast(message) {
        const t = $('#toast');
        t.textContent = message;
        t.classList.add('show');
        clearTimeout(toastTimer);
        toastTimer = setTimeout(() => t.classList.remove('show'), 1800);
    }
    async function copy(text, what) {
        try {
            await navigator.clipboard.writeText(text);
        } catch {
            const area = el('textarea');
            area.value = text;
            document.body.append(area);
            area.select();
            document.execCommand('copy');
            area.remove();
        }
        toast(`已复制 ${what || text}`);
    }

    // ---------- swatches ----------
    function swatch(hex, title, { extra = '', cls = '' } = {}) {
        const fg = bestText(hex);
        const button = el('button', {
            type: 'button', class: `swatch ${cls}`.trim(), 'data-copy': hex,
            'aria-label': `${title} ${hex}，白字 ${fmt(contrast(WHITE, hex))}，墨字 ${fmt(contrast(INK, hex))}。点击复制`
        });
        button.style.background = hex;
        button.style.color = fg;
        button.innerHTML = `${extra}<b>${title}</b><span class="hex">${hex}</span>` +
            `<span class="ratios">白 ${contrast(WHITE, hex).toFixed(1)} · 墨 ${contrast(INK, hex).toFixed(1)}</span>`;
        return button;
    }
    function coreColours() {
        const t = tokens(), p = N.palettes[state.palette];
        return [
            { hex: t.primary, name: `主色 · ${p.name}`, en: state.palette === 'board' ? 'Nodu Blue' : p.tag, role: N.core.blue.role },
            { hex: N.core.gold.hex, name: N.core.gold.name, en: N.core.gold.en, role: N.core.gold.role },
            { hex: N.core.ink.hex, name: N.core.ink.name, en: N.core.ink.en, role: N.core.ink.role },
            { hex: N.core.paper.hex, name: N.core.paper.name, en: N.core.paper.en, role: N.core.paper.role }
        ];
    }
    function renderCore() {
        const strip = $('#core-strip');
        strip.replaceChildren(...coreColours().map(c => swatch(c.hex, c.name)));
        const grid = $('#core-grid');
        grid.replaceChildren(...coreColours().map(c => {
            const card = el('article', { class: 'core-card' });
            card.append(swatch(c.hex, c.name, { extra: '<span class="sample">Aa 运行</span>' }));
            const w = contrast(WHITE, c.hex), k = contrast(INK, c.hex);
            const badge = (name, v) => `<span class="ratio-badge ${v >= 4.5 ? 'pass' : v >= 3 ? '' : 'fail'}">${name} ${fmt(v)} · ${grade(v)}</span>`;
            card.append(el('div', { class: 'core-info' },
                `<div class="name">${c.name}<span>${c.hex}</span></div><div class="meta">${c.en} · RGB ${rgbText(c.hex)}</div>` +
                `<div class="role">${c.role}</div><div class="badges">${badge('白字', w)}${badge('墨字', k)}</div>`));
            return card;
        }));
    }
    function renderRamps() {
        const p = N.palettes[state.palette];
        const ramp = (title, note, items) => {
            const box = el('div', { class: 'ramp' }, `<h3>${title}<small>${note}</small></h3>`);
            const row = el('div', { class: 'ramp-row' });
            row.append(...items);
            box.append(row);
            return box;
        };
        const primaryHex = tokens().primary;
        const lists = [
            ramp(`主色色阶 · ${p.name}`, '500 主色 · 300 深底文字与焦点 · 600 浅底文字与按下 · 50 / 100 浅色选中',
                p.ramp.map(([step, hex]) => swatch(hex, step, { cls: hex === primaryHex ? 'is-brand' : '' }))),
            ramp('点亮黄色阶', '400 为品牌色；斜纹格（500–900）只用于印刷和插画',
                N.signalRamp.map(([step, hex]) => swatch(hex, step, { cls: `${step === '400' ? 'is-brand' : ''} ${Number(step) >= 500 ? 'print' : ''}` }))),
            ...THEMES.map(theme => ramp(theme === 'dark' ? '深色工作台 · 冷石墨' : '浅色工作台 · 暖纸',
                theme === 'dark' ? '与蓝色同一色相，去掉了 SCOPE 时期的青绿色偏' : '保留阅读感，暖色与点亮黄同调',
                NEUTRAL_KEYS.map(([key, name]) => swatch(N.neutrals[theme][key], name))))
        ];
        $('#ramp-list').replaceChildren(...lists);
    }

    // ---------- code ----------
    function renderSyntax() {
        const t = tokens(), body = $('#syntax-table tbody');
        body.replaceChildren(...Object.entries(N.syntax[state.theme]).map(([key, hex]) => {
            const v = contrast(hex, t.editor);
            return el('tr', {}, `<td>${SYNTAX_LABELS[key]}</td><td><span class="token-sample" style="color:${hex};background:${t.editor}">${key === 'string' ? '"blink"' : key === 'number' ? '500' : key === 'comment' ? '# 注释' : key}</span></td>` +
                `<td class="mono">${hex}</td><td><span class="ratio-badge ${v >= 4.5 ? 'pass' : 'fail'}">${fmt(v)}</span></td>`);
        }));
    }
    function renderAnsi() {
        const t = tokens();
        $('#ansi-grid').replaceChildren(...N.ansi[state.theme].map((hex, i) => {
            const name = `${i >= 8 ? 'bright ' : ''}${N.ansiNames[i % 8]}`;
            const exempt = i === 0 || i === 8;
            const cell = el('div', { class: 'ansi-cell' });
            const chip = el('div', { class: 'chip-color' });
            chip.style.background = hex;
            cell.append(chip, el('div', { class: 'ansi-meta' },
                `<b style="color:${exempt ? 'var(--nd-text)' : hex}">${i} ${name}</b><span>${hex}</span><span>${exempt ? '背景用' : fmt(contrast(hex, t.terminal))}</span>`));
            return cell;
        }));
    }

    // ---------- contrast ----------
    function renderChecks() {
        const t = tokens(), list = N.checks[state.palette][state.theme];
        const passed = list.filter(c => c.pass).length;
        $('#check-summary').textContent = `${N.palettes[state.palette].name} · ${state.theme === 'dark' ? '深色' : '浅色'}：${passed} / ${list.length} 项达标`;
        $('#check-table tbody').replaceChildren(...list.map(c => el('tr', {},
            `<td>${c.label}</td><td><span class="sample" style="color:${t[c.fg]};background:${t[c.bg]}">Aa 运行</span></td>` +
            `<td class="mono">${fmt(c.value)}</td><td>${c.pass ? `<span class="ok-mark">✓</span> ≥ ${c.min}` : `<span class="bad-mark">✗</span> ≥ ${c.min}`}</td>`)));
    }
    function fillCheckerOptions() {
        const keys = Object.keys(tokens()).filter(k => /^#[0-9A-F]{6}$/i.test(tokens()[k]));
        for (const [id, fallback] of [['#fg-select', 'text'], ['#bg-select', 'editor']]) {
            const select = $(id), current = select.value || fallback;
            select.replaceChildren(...keys.map(k => el('option', { value: k }, `${label(k)} · ${tokens()[k]}`)));
            select.value = keys.includes(current) ? current : fallback;
        }
    }
    function renderChecker() {
        const t = tokens(), fg = t[$('#fg-select').value], bg = t[$('#bg-select').value];
        const sample = $('#checker-sample');
        sample.style.color = fg;
        sample.style.background = bg;
        const v = contrast(fg, bg);
        const tags = [['正文 AA 4.5', v >= 4.5], ['大字 / 图形 3', v >= 3], ['AAA 7', v >= 7]]
            .map(([n, ok]) => `<span class="ratio-badge ${ok ? 'pass' : 'fail'}">${ok ? '✓' : '✗'} ${n}</span>`).join(' ');
        $('#checker-ratio').innerHTML = `<strong>${fmt(v)}</strong>${tags}`;
    }

    // ---------- export ----------
    function renderExport() {
        const t = tokens(), p = N.palettes[state.palette];
        $('#export-label').textContent = `${p.name} · ${state.theme === 'dark' ? '深色' : '浅色'} · ${Object.keys(t).length} 个变量`;
        $('#export-code').textContent = `/* Nodu · 见微 — ${p.name}（${p.tag}）· ${state.theme} */\n:root {\n` +
            Object.entries(t).map(([k, v]) => `  --nd-${k}: ${v};`).join('\n') + '\n}';
    }

    // ---------- apply ----------
    function apply() {
        Object.assign(root.dataset, state);
        for (const b of $$('[data-set-palette]')) b.setAttribute('aria-pressed', String(b.dataset.setPalette === state.palette));
        for (const b of $$('[data-set-theme]')) b.setAttribute('aria-pressed', String(b.dataset.setTheme === state.theme));
        $('#cvd').value = state.cvd;
        const p = N.palettes[state.palette];
        $('#palette-summary').textContent = `当前：${p.name}（${p.tag}）· ${state.theme === 'dark' ? '深色' : '浅色'}主题。${p.summary}`;
        renderCore();
        renderRamps();
        renderSyntax();
        renderAnsi();
        renderChecks();
        fillCheckerOptions();
        renderChecker();
        renderExport();
        const q = new URLSearchParams(state);
        if (state.cvd === 'none') q.delete('cvd');
        history.replaceState(null, '', `${location.pathname}?${q}${location.hash}`);
    }

    // ---------- events ----------
    document.addEventListener('click', event => {
        const target = event.target.closest('[data-set-palette],[data-set-theme],[data-copy],#led-toggle,#copy-css');
        if (!target) return;
        if (target.dataset.setPalette) { state.palette = target.dataset.setPalette; apply(); }
        else if (target.dataset.setTheme) { state.theme = target.dataset.setTheme; apply(); }
        else if (target.dataset.copy) copy(target.dataset.copy);
        else if (target.id === 'copy-css') copy($('#export-code').textContent, 'CSS 变量');
        else if (target.id === 'led-toggle') {
            const lit = target.getAttribute('aria-pressed') !== 'true';
            target.setAttribute('aria-pressed', String(lit));
            target.querySelector('span').textContent = lit ? '熄灭' : '点亮';
            $('#hero-icon').dataset.lit = String(lit);
        }
    });
    $('#cvd').addEventListener('change', event => { state.cvd = event.target.value; apply(); });
    $('#fg-select').addEventListener('change', renderChecker);
    $('#bg-select').addEventListener('change', renderChecker);
    $('#range-demo').addEventListener('input', event => { $('#range-out').textContent = event.target.value; });

    injectLogos();
    apply();
})();
